const inputItem = $input.first();
const incoming = inputItem && inputItem.json !== null && typeof inputItem.json === 'object'
  && !Array.isArray(inputItem.json)
  ? inputItem.json
  : {};

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

const hasWebhookBody = Object.prototype.hasOwnProperty.call(incoming, 'body');
if (hasWebhookBody && !isRecord(incoming.body)) {
  throw new Error('Webhook body must be a JSON object');
}
const source = hasWebhookBody ? incoming.body : incoming;
const allowedFields = [
  'target_domain',
  'keywords',
  'competitor_domains',
  'region',
  'country_code',
  'language',
  'language_code',
  'search_depth',
  'trigger_source'
];
const config = {};
for (const field of allowedFields) {
  if (Object.prototype.hasOwnProperty.call(source, field)) config[field] = source[field];
}

function normalizeDomain(value) {
  if (typeof value !== 'string') return '';
  const raw = value.trim().toLowerCase();
  if (!raw || raw.length > 2048 || /\s|\\/.test(raw)) return '';

  let remainder = raw;
  const scheme = remainder.match(/^([a-z][a-z0-9+.-]*):\/\//);
  if (scheme) {
    if (!['http', 'https'].includes(scheme[1])) return '';
    remainder = remainder.slice(scheme[0].length);
  }

  let authority = remainder.split(/[/?#]/, 1)[0];
  if (!authority || authority.includes('@')) return '';
  const port = authority.match(/:(\d{1,5})$/);
  if (port) {
    if (Number(port[1]) > 65535) return '';
    authority = authority.slice(0, -port[0].length);
  }
  if (authority.includes(':')) return '';

  const hostname = authority.replace(/^www\./, '').replace(/\.$/, '');
  if (hostname.length > 253 || !hostname.includes('.') || /^\d+(?:\.\d+){3}$/.test(hostname)) return '';
  const labelsAreValid = hostname.split('.').every((label) => (
    label.length > 0
    && label.length <= 63
    && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label)
  ));
  return labelsAreValid ? hostname : '';
}

function splitList(value, label, maximumEntryLength, allowMissing = false) {
  const normalizedValue = value === undefined && allowMissing ? '' : value;
  let sourceValues;
  if (typeof normalizedValue === 'string') {
    if (normalizedValue.length > 5000) {
      throw new Error(label + ' string must be at most 5000 characters');
    }
    sourceValues = normalizedValue.split(/[\n,]/);
  } else if (Array.isArray(normalizedValue)) {
    if (normalizedValue.length > 100) {
      throw new Error(label + ' array is limited to 100 raw entries');
    }
    if (!normalizedValue.every((entry) => typeof entry === 'string')) {
      throw new Error(label + ' must be a string or an array of strings');
    }
    sourceValues = normalizedValue;
  } else {
    throw new Error(label + ' must be a string or an array of strings');
  }

  const seen = new Set();
  return sourceValues
    .map((entry) => {
      if (entry.length > maximumEntryLength) {
        throw new Error(label + ' entries must be at most ' + maximumEntryLength + ' characters');
      }
      return entry.trim();
    })
    .filter((entry) => {
      const key = entry.toLowerCase();
      if (!entry || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function boundedText(value, label, fallback) {
  const resolved = value === undefined ? fallback : value;
  if (typeof resolved !== 'string') throw new Error(label + ' must be a string');
  const normalized = resolved.trim();
  if (!normalized) throw new Error(label + ' is required');
  if (resolved.length > 100) throw new Error(label + ' must be at most 100 characters');
  return normalized;
}

function buildGoogleUule(location) {
  const normalized = String(location || '').trim();
  if (!normalized) return '';
  return 'w+CAIQICI' + Buffer.from(normalized, 'utf8').toString('base64');
}

const targetDomain = normalizeDomain(config.target_domain);
if (!targetDomain) {
  throw new Error('target_domain must be a valid domain, for example talordata.com');
}

const keywords = splitList(config.keywords, 'keywords', 200);
if (keywords.length === 0) throw new Error('keywords must contain at least one keyword');
if (keywords.length > 20) {
  throw new Error('keywords is limited to 20 unique values per run to keep API usage predictable');
}

const competitorInputs = splitList(config.competitor_domains, 'competitor_domains', 2048, true);
const normalizedCompetitors = competitorInputs.map((value) => normalizeDomain(value));
if (normalizedCompetitors.some((value) => !value)) {
  throw new Error('competitor_domains contains an invalid domain');
}
const competitorDomains = [...new Set(normalizedCompetitors.filter((value) => value !== targetDomain))];
if (competitorDomains.length > 20) {
  throw new Error('competitor_domains is limited to 20 unique values per run');
}

const searchDepth = config.search_depth === undefined ? 30 : config.search_depth;
if (typeof searchDepth !== 'number' || ![20, 30].includes(searchDepth)) {
  throw new Error('search_depth must be a number equal to 20 or 30');
}
const region = boundedText(config.region, 'region', 'United States');
const uule = buildGoogleUule(region);
const language = boundedText(config.language, 'language', 'English');
const countryCode = boundedText(config.country_code, 'country_code', 'us').toLowerCase();
if (!/^[a-z]{2}$/.test(countryCode)) {
  throw new Error('country_code must be a two-letter Google country code such as us');
}
const languageCode = boundedText(config.language_code, 'language_code', 'en').toLowerCase();
if (!/^[a-z]{2,5}(?:-[a-z]{2,5})?$/.test(languageCode)) {
  throw new Error('language_code must be a Google language code such as en');
}

const triggerSource = hasWebhookBody
  ? 'webhook'
  : (typeof config.trigger_source === 'string' && config.trigger_source.trim()
      ? config.trigger_source.trim().slice(0, 40)
      : 'manual');
const runTime = new Date().toISOString();
const executionPart = String($execution && $execution.id ? $execution.id : 'manual')
  .replace(/[^A-Za-z0-9_-]/g, '')
  .slice(-12) || 'manual';
const runId = 'seo-' + runTime.replace(/\D/g, '').slice(0, 14) + '-' + executionPart;

return keywords.map((keyword, index) => ({
  json: {
    run_id: runId,
    run_time: runTime,
    keyword,
    task_index: index,
    keywords_count: keywords.length,
    estimated_api_calls: keywords.length,
    trigger_source: triggerSource,
    target_domain: targetDomain,
    competitor_domains: competitorDomains,
    region,
    uule,
    country_code: countryCode,
    language,
    language_code: languageCode,
    search_depth: searchDepth,
    no_cache: false
  }
}));

const evidenceBundle = (await (async () => {
const tasks = $('Set SEO Brief').all()
  .map((item) => item && item.json)
  .filter((task) => task && typeof task === 'object' && !Array.isArray(task))
  .sort((left, right) => Number(left.task_index) - Number(right.task_index));

if (tasks.length === 0) {
  throw new Error('No prepared search tasks were found');
}

const tasksByIndex = new Map();
for (const task of tasks) {
  const taskIndex = Number(task.task_index);
  if (!Number.isInteger(taskIndex) || taskIndex < 0 || tasksByIndex.has(taskIndex)) {
    throw new Error('Prepared search tasks must have unique zero-based task_index values');
  }
  tasksByIndex.set(taskIndex, task);
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function canonicalizeInspectionName(value) {
  let current = String(value || '');
  for (let iteration = 0; iteration < 8; iteration += 1) {
    let decoded;
    try {
      decoded = decodeURIComponent(current);
    } catch (error) {
      return null;
    }
    if (decoded === current) {
      return /%[0-9a-f]{2}/i.test(current) ? null : current;
    }
    current = decoded;
  }
  return /%[0-9a-f]{2}/i.test(current) ? null : current;
}

function normalizeEvidenceUrl(value) {
  const raw = String(value || '').trim();
  if (raw.length > 8192 || /[\s\u0000-\u001f\\]/.test(raw)) return null;
  const scheme = raw.match(/^(https?):\/\//i);
  if (!scheme) return null;

  const remainder = raw.slice(scheme[0].length);
  const boundary = remainder.search(/[/?#]/);
  let authority = boundary === -1 ? remainder : remainder.slice(0, boundary);
  if (!authority || authority.includes('@')) return null;
  const port = authority.match(/:(\d{1,5})$/);
  if (port) {
    if (Number(port[1]) > 65535) return null;
    authority = authority.slice(0, -port[0].length);
  }
  if (authority.includes(':')) return null;

  const hostname = authority.toLowerCase().replace(/^www\./, '').replace(/\.$/, '');
  const validLabels = hostname.length <= 253 && hostname.split('.').every((label) => (
    label.length > 0
    && label.length <= 63
    && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label)
  ));
  if (!validLabels) return null;

  const sensitiveName = /(?:authorization|api[-_ ]?key|token|secret|credential|password|passphrase|private[-_ ]?key|session|cookie)/i;
  const hashIndex = raw.indexOf('#');
  const queryIndex = raw.indexOf('?');
  const parameterSections = [];
  if (queryIndex !== -1) {
    parameterSections.push(raw.slice(queryIndex + 1, hashIndex === -1 ? raw.length : hashIndex));
  }
  if (hashIndex !== -1) parameterSections.push(raw.slice(hashIndex + 1));
  for (const section of parameterSections) {
    for (const parameter of section.split('&')) {
      const key = parameter.split('=', 1)[0].replace(/\+/g, ' ');
      if (!key) continue;
      const inspectedKey = canonicalizeInspectionName(key);
      if (inspectedKey === null || sensitiveName.test(inspectedKey)) return null;
    }
  }

  return { link: raw, domain: hostname };
}

function sanitizeErrorValue(value, depth = 0, seen = new WeakSet()) {
  if (typeof value === 'string') {
    const candidate = value.trim();
    if (depth < 4 && (/^\{/.test(candidate) || /^\[/.test(candidate))) {
      try {
        const parsed = JSON.parse(candidate);
        if (isRecord(parsed) || Array.isArray(parsed)) {
          return sanitizeErrorValue(parsed, depth + 1, seen);
        }
      } catch (error) {}
    }
    return value
      .replace(
        /["'](?:authorization|api[-_ ]?key|token|secret|credential|password|passphrase|private[-_ ]?key|session|cookie|headers?)["']\s*[:=]\s*["'][^"']*["']/gi,
        'sensitive_value: [REDACTED]'
      )
      .replace(/(https?:\/\/)[^/\s:@]+:[^@\s/]+@/gi, '$1[REDACTED]@')
      .replace(/authorization\s*[:=]\s*(?:bearer\s+)?[^\s,;]+/gi, 'Authorization: [REDACTED]')
      .replace(/bearer\s+[^\s,;]+/gi, 'Bearer [REDACTED]')
      .replace(/sk[-_][A-Za-z0-9_-]+/gi, 'sk_[REDACTED]')
      .replace(/api[-_ ]?key\s*[:=]\s*[^\s,;]+/gi, 'api_key: [REDACTED]')
      .replace(
        /\b(token|secret|credential|password|passphrase|session)\s*[:=]\s*[^\s,;]+/gi,
        '$1: [REDACTED]'
      )
      .replace(
        /\b(private[-_ ]?key|client[-_ ]?secret|access[-_ ]?token)\s*[:=]\s*[^\s,;]+/gi,
        'sensitive_value: [REDACTED]'
      );
  }
  if (value === null || ['number', 'boolean'].includes(typeof value)) return value;
  if (depth >= 4) return '[TRUNCATED]';
  if (!isRecord(value) && !Array.isArray(value)) return String(value || '');
  if (seen.has(value)) return '[CIRCULAR]';
  seen.add(value);
  if (Array.isArray(value)) {
    return value.slice(0, 20).map((entry) => sanitizeErrorValue(entry, depth + 1, seen));
  }

  const sanitized = {};
  for (const [key, entry] of Object.entries(value).slice(0, 50)) {
    if (
      /(?:authorization|api[-_ ]?key|token|secret|credential|password|passphrase|private[-_ ]?key|session|cookie|headers?)/i.test(key)
    ) {
      sanitized[key] = '[REDACTED]';
    } else {
      sanitized[key] = sanitizeErrorValue(entry, depth + 1, seen);
    }
  }
  return sanitized;
}

function redactError(value) {
  const sanitized = sanitizeErrorValue(value);
  let message;
  try {
    message = typeof sanitized === 'string' ? sanitized : JSON.stringify(sanitized);
  } catch (error) {
    message = 'Unknown TalorData response error';
  }
  return String(message || 'Unknown TalorData response error')
    .replace(/(https?:\/\/)[^/\s:@]+:[^@\s/]+@/gi, '$1[REDACTED]@')
    .replace(/authorization\s*[:=]\s*(?:bearer\s+)?[^\s,;]+/gi, 'Authorization: [REDACTED]')
    .replace(/bearer\s+[^\s,;]+/gi, 'Bearer [REDACTED]')
    .replace(/sk[-_][A-Za-z0-9_-]+/gi, 'sk_[REDACTED]')
    .replace(/api[-_ ]?key\s*[:=]\s*[^\s,;]+/gi, 'api_key: [REDACTED]')
    .slice(0, 500);
}

function acceptedCode(code) {
  return code === undefined
    || code === null
    || code === 0
    || code === '0'
    || code === 200
    || code === '200';
}

function envelopeStatus(value) {
  if (!isRecord(value)) {
    return { ok: false, message: 'TalorData returned an empty or non-object response' };
  }

  const httpStatus = Number(value.statusCode ?? value.http_status);
  if (Number.isFinite(httpStatus) && httpStatus >= 400) {
    return {
      ok: false,
      message: redactError(value.message || value.error || value.body || ('TalorData HTTP error: ' + httpStatus))
    };
  }

  const code = value.code ?? value.error_code ?? value.status_code;
  if (!acceptedCode(code)) {
    return {
      ok: false,
      message: redactError(
        value.message
        || value.error
        || value.msg
        || value.data
        || ('TalorData business error: ' + code)
      )
    };
  }

  if (value.error) {
    return {
      ok: false,
      message: redactError(value.error.message || value.error)
    };
  }

  return { ok: true, message: '' };
}

function unwrapAndValidateEnvelope(value) {
  let current = value;
  for (let depth = 0; depth < 4; depth += 1) {
    const status = envelopeStatus(current);
    if (!status.ok) {
      return { ok: false, message: status.message, payload: null };
    }
    if (isRecord(current.data) && Object.prototype.hasOwnProperty.call(current.data, 'json')) {
      const embedded = current.data.json;
      if (isRecord(embedded)) {
        current = embedded;
        continue;
      }
      if (typeof embedded !== 'string' || embedded.length > 2000000) {
        return { ok: false, message: 'TalorData data.json was not a supported JSON object', payload: null };
      }
      try {
        const parsed = JSON.parse(embedded);
        if (!isRecord(parsed)) {
          return { ok: false, message: 'TalorData data.json was not a supported JSON object', payload: null };
        }
        current = parsed;
        continue;
      } catch (error) {
        return { ok: false, message: 'TalorData data.json was not valid JSON', payload: null };
      }
    }
    if (isRecord(current.data)) {
      current = current.data;
      continue;
    }
    if (isRecord(current.result)) {
      current = current.result;
      continue;
    }
    return { ok: true, message: '', payload: current };
  }
  return {
    ok: false,
    message: 'TalorData response envelope exceeded the supported nesting depth',
    payload: null
  };
}

function searchStatus(value) {
  if (!isRecord(value)) {
    return { ok: false, message: 'TalorData returned an empty or non-object search payload' };
  }
  const metadata = value.search_metadata;
  if (!isRecord(metadata) || metadata.status === undefined || metadata.status === null) {
    return { ok: true, message: '' };
  }
  const status = String(metadata.status).trim().toLowerCase();
  if (['success', 'complete', 'completed'].includes(status)) {
    return { ok: true, message: '' };
  }
  return {
    ok: false,
    message: redactError(
      metadata.message
      || metadata.error
      || ('TalorData search status: ' + metadata.status)
    )
  };
}

function normalizeOrganicResults(value, searchDepth) {
  if (!isRecord(value)) return null;
  let source = null;
  if (Array.isArray(value.organic_results)) source = value.organic_results;
  else if (Array.isArray(value.organic)) source = value.organic;
  if (source === null) return null;

  return source
    .map((result, index) => {
      if (!isRecord(result)) return null;
      const parsedPosition = Number(result.position ?? result.rank ?? index + 1);
      const position = Number.isFinite(parsedPosition) && parsedPosition > 0
        ? parsedPosition
        : index + 1;
      const evidenceUrl = normalizeEvidenceUrl(result.link ?? result.url ?? '');
      if (!evidenceUrl) return null;
      return {
        position,
        title: String(result.title ?? '').trim(),
        snippet: String(result.snippet ?? result.description ?? '').trim(),
        link: evidenceUrl.link,
        domain: evidenceUrl.domain
      };
    })
    .filter((result) => result && result.link && result.domain && result.position <= searchDepth)
    .sort((left, right) => left.position - right.position);
}

function pairedTaskIndexes(item) {
  const pairedItems = Array.isArray(item && item.pairedItem)
    ? item.pairedItem
    : [item && item.pairedItem];
  return pairedItems
    .map((pairedItem) => Number(pairedItem && pairedItem.item))
    .filter((taskIndex) => Number.isInteger(taskIndex) && taskIndex >= 0);
}

const responsesByTaskIndex = new Map();
for (const responseItem of $input.all()) {
  const taskIndex = pairedTaskIndexes(responseItem)
    .find((candidate) => tasksByIndex.has(candidate));
  if (taskIndex !== undefined && !responsesByTaskIndex.has(taskIndex)) {
    responsesByTaskIndex.set(taskIndex, responseItem);
  }
}

function normalizeSearch(task) {
  const responseItem = responsesByTaskIndex.get(task.task_index);
  if (!responseItem) {
    return {
      task_index: task.task_index,
      keyword: task.keyword,
      search_status: 'failed',
      error_message: 'No TalorData response received for this search task',
      organic_results: []
    };
  }

  const responseValue = responseItem && responseItem.json !== undefined
    ? responseItem.json
    : responseItem;
  const providerValue = isRecord(responseValue)
    && responseValue.engine === 'google'
    && Object.prototype.hasOwnProperty.call(responseValue, 'raw')
    ? responseValue.raw
    : responseValue;
  const outerStatus = envelopeStatus(providerValue);
  if (!outerStatus.ok) {
    return {
      task_index: task.task_index,
      keyword: task.keyword,
      search_status: 'failed',
      error_message: outerStatus.message,
      organic_results: []
    };
  }

  const payload = isRecord(providerValue) && Object.prototype.hasOwnProperty.call(providerValue, 'body')
    ? providerValue.body
    : providerValue;
  const unwrapped = unwrapAndValidateEnvelope(payload);
  if (!unwrapped.ok) {
    return {
      task_index: task.task_index,
      keyword: task.keyword,
      search_status: 'failed',
      error_message: unwrapped.message,
      organic_results: []
    };
  }

  const searchPayload = unwrapped.payload;
  const metadataStatus = searchStatus(searchPayload);
  if (!metadataStatus.ok) {
    return {
      task_index: task.task_index,
      keyword: task.keyword,
      search_status: 'failed',
      error_message: metadataStatus.message,
      organic_results: []
    };
  }

  const organicResults = normalizeOrganicResults(searchPayload, task.search_depth);
  if (organicResults === null) {
    return {
      task_index: task.task_index,
      keyword: task.keyword,
      search_status: 'failed',
      error_message: 'TalorData response did not contain a supported Google organic result structure',
      organic_results: []
    };
  }

  return {
    task_index: task.task_index,
    keyword: task.keyword,
    search_status: 'success',
    error_message: '',
    organic_results: organicResults
  };
}

const first = tasks[0];
const searches = tasks.map(normalizeSearch);

return [{
  json: {
    trigger_source: first.trigger_source,
    config: {
      target_domain: first.target_domain,
      region: first.region,
      country_code: first.country_code,
      language: first.language,
      language_code: first.language_code,
      search_depth: first.search_depth
    },
    tasks,
    searches,
    run_id: first.run_id,
    run_time: first.run_time,
    estimated_api_calls: tasks.length
  }
}];
})())[0].json;
const tasks = Array.isArray(evidenceBundle.tasks) ? evidenceBundle.tasks : [];
const searches = Array.isArray(evidenceBundle.searches) ? evidenceBundle.searches : [];
if (tasks.length === 0) {
  throw new Error('No normalized search tasks were found');
}

const limitation = 'This report is based only on the returned Google Search results from TalorData. It does not include search volume, website traffic, backlinks, technical SEO audit, or historical rankings unless those data sources are connected separately.';
const rankingLimitation = 'Position is based on the current TalorData Google Search response, not a dedicated historical rank tracker.';

function domainMatches(actualDomain, configuredDomain) {
  return actualDomain === configuredDomain || actualDomain.endsWith('.' + configuredDomain);
}

function uniqueLinks(values, limit = Infinity) {
  return [...new Set(values.filter(Boolean))].slice(0, limit);
}

function publicFailureMessage(value) {
  const diagnostic = String(value || '').toLowerCase();
  if (/no talordata response received/.test(diagnostic)) {
    return 'No TalorData response was received for this search task.';
  }
  if (/rate\s*limit|429/.test(diagnostic)) {
    return 'TalorData rate limit prevented this search.';
  }
  if (/\bhttp\b|service unavailable|provider unavailable|statuscode|(?:^|\D)5\d{2}(?:\D|$)/.test(diagnostic)) {
    return 'TalorData HTTP request failed.';
  }
  if (/search status|search provider|provider rejected|rejected the request|search_metadata/.test(diagnostic)) {
    return 'TalorData provider or search status failed.';
  }
  return 'TalorData request failed.';
}

const tasksByIndex = new Map(tasks.map((task) => [task.task_index, task]));
const visibilitySummary = [];
const competitorPresence = [];
const keywordOpportunities = [];
const recommendations = [];
const failures = [];
const sourceLinks = [];

for (const search of searches) {
  const task = tasksByIndex.get(search.task_index);
  if (!task) continue;

  if (search.search_status !== 'success') {
    const errorMessage = publicFailureMessage(search.error_message);
    failures.push({ keyword: task.keyword, error: errorMessage });
    visibilitySummary.push({
      run_id: task.run_id,
      keyword: task.keyword,
      target_domain: task.target_domain,
      target_found: false,
      target_rank_in_results: null,
      target_url: '',
      visibility_label: 'Search failed',
      search_status: 'failed',
      error_message: errorMessage,
      evidence_link: '',
      serp_evidence: [],
      serp_evidence_json: '[]',
      limitation: 'No ranking or opportunity conclusion was produced because this keyword search failed.'
    });
    continue;
  }

  const results = Array.isArray(search.organic_results)
    ? search.organic_results
    : [];
  for (const result of results) sourceLinks.push(result.link);

  const targetResult = results.find((result) => domainMatches(result.domain, task.target_domain));
  const targetFound = Boolean(targetResult);
  const targetRank = targetFound ? targetResult.position : null;
  const visibilityLabel = !targetFound
    ? 'Not found'
    : targetRank <= 10
      ? 'Strong visibility'
      : 'Weak visibility';
  const serpEvidence = results.slice(0, 5).map((result) => ({
    rank: result.position,
    title: result.title,
    snippet: result.snippet,
    link: result.link,
    domain: result.domain
  }));

  visibilitySummary.push({
    run_id: task.run_id,
    keyword: task.keyword,
    target_domain: task.target_domain,
    target_found: targetFound,
    target_rank_in_results: targetRank,
    target_url: targetResult ? targetResult.link : '',
    visibility_label: visibilityLabel,
    search_status: 'success',
    error_message: '',
    evidence_link: targetResult ? targetResult.link : (results[0] ? results[0].link : ''),
    serp_evidence: serpEvidence,
    serp_evidence_json: JSON.stringify(serpEvidence),
    limitation: rankingLimitation
  });

  const competitorRows = task.competitor_domains.map((competitorDomain) => {
    const competitorResult = results.find((result) => domainMatches(result.domain, competitorDomain));
    const competitorFound = Boolean(competitorResult);
    const aboveTarget = competitorFound
      && (!targetFound || competitorResult.position < targetRank);
    const row = {
      run_id: task.run_id,
      keyword: task.keyword,
      competitor_domain: competitorDomain,
      competitor_found: competitorFound,
      competitor_rank: competitorFound ? competitorResult.position : null,
      competitor_url: competitorFound ? competitorResult.link : '',
      above_target: aboveTarget,
      evidence_link: competitorFound ? competitorResult.link : ''
    };
    competitorPresence.push(row);
    return row;
  });

  const competitorsTopFive = competitorRows
    .filter((row) => row.competitor_found && row.competitor_rank <= 5);
  const competitorsAboveTarget = competitorRows.filter((row) => row.above_target);
  const patternResults = results
    .filter((result) => /\b(comparison|alternative|alternatives|best|top|vs\.?)(\b|$)/i.test(result.title));
  const basis = [];
  let score = 0;

  if (!targetFound) {
    basis.push('target_domain_not_found');
    score += 3;
  }
  if (targetFound && targetRank > 10) {
    basis.push('target_visibility_below_top_10');
    score += 2;
  }
  if (competitorsTopFive.length > 0) {
    basis.push('competitor_found_top_5');
    score += 2;
  }
  if (competitorsAboveTarget.length > 0) {
    basis.push('competitor_above_target');
    score += 1;
  }
  if (patternResults.length > 0) {
    basis.push('comparison_or_list_pages_present');
    score += 1;
  }
  if (basis.length === 0) basis.push('target_visible_top_10');

  const opportunityLevel = score >= 4 ? 'High' : score >= 2 ? 'Medium' : 'Low';
  let recommendedAction = 'Maintain the current page and re-check this keyword in a later run.';
  if (!targetFound) {
    recommendedAction = 'Create or optimize a page that directly addresses this keyword and the dominant returned result format.';
  } else if (targetRank > 10) {
    recommendedAction = 'Improve the target page title, snippet alignment, and topical coverage for this keyword.';
  } else if (competitorsAboveTarget.length > 0) {
    recommendedAction = 'Review the evidence pages above the target and strengthen a clearly differentiated page for this keyword.';
  } else if (competitorsTopFive.length > 0) {
    recommendedAction = 'Review the high-ranking competitor evidence pages and strengthen a clearly differentiated page for this keyword.';
  } else if (patternResults.length > 0) {
    recommendedAction = 'Consider a comparison or alternatives page because that format appears in the returned result titles.';
  }

  const evidenceLinks = uniqueLinks([
    targetResult ? targetResult.link : '',
    ...competitorsTopFive.map((row) => row.evidence_link),
    ...patternResults.map((result) => result.link),
    ...results.slice(0, 2).map((result) => result.link)
  ], 5);
  const opportunity = {
    run_id: task.run_id,
    keyword: task.keyword,
    opportunity_level: opportunityLevel,
    basis,
    recommended_action: recommendedAction,
    recommendation_type: 'Evidence-based Recommendation',
    evidence_links: evidenceLinks,
    limitation: 'Opportunity is inferred only from the returned SERP positions, titles, snippets, and links.'
  };
  keywordOpportunities.push(opportunity);
  recommendations.push({
    keyword: task.keyword,
    recommendation: recommendedAction,
    type: opportunity.recommendation_type,
    evidence_links: evidenceLinks,
    reason: basis.join(', '),
    limitation: opportunity.limitation
  });
}

