const factsItem = $('Normalize SERP Evidence').first();
const facts = factsItem && factsItem.json;
if (facts === null || typeof facts !== 'object' || Array.isArray(facts)) {
  throw new Error('Prepared SEO results are required');
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function boundedText(value, maximumLength) {
  if (!['string', 'number', 'boolean'].includes(typeof value)) return '';
  return String(value)
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maximumLength);
}

const currentItem = $input.first();
const current = currentItem && isRecord(currentItem.json) ? currentItem.json : {};
if (Object.prototype.hasOwnProperty.call(current, 'error')) {
  throw new Error('Analyze SEO Visibility and Opportunities failed');
}

let candidate = Object.prototype.hasOwnProperty.call(current, 'output') ? current.output : current;
if (typeof candidate === 'string') {
  if (candidate.length > 100000) {
    throw new Error('SEO analysis output exceeded the size limit');
  }
  const trimmed = candidate.trim();
  const fenced = trimmed.match(/^\x60\x60\x60(?:json)?\s*([\s\S]*?)\s*\x60\x60\x60$/i);
  try {
    candidate = JSON.parse(fenced ? fenced[1] : trimmed);
  } catch (error) {
    throw new Error('SEO analysis output was not valid JSON');
  }
}
if (!isRecord(candidate) || Object.keys(candidate).length === 0) {
  throw new Error('SEO analysis output was not valid JSON');
}

const allowedKeywords = new Set(
  Array.isArray(facts.ai_input && facts.ai_input.allowed_keywords)
    ? facts.ai_input.allowed_keywords.filter((value) => typeof value === 'string')
    : []
);
const allowedEvidenceLinks = new Set(
  Array.isArray(facts.ai_input && facts.ai_input.allowed_evidence_links)
    ? facts.ai_input.allowed_evidence_links.filter((value) => typeof value === 'string')
    : []
);
let partial = false;

function evidenceLinks(value) {
  if (!Array.isArray(value)) {
    partial = true;
    return [];
  }
  const seen = new Set();
  const links = [];
  for (const rawLink of value.slice(0, 25)) {
    if (typeof rawLink !== 'string' || !allowedEvidenceLinks.has(rawLink) || seen.has(rawLink)) {
      partial = true;
      continue;
    }
    seen.add(rawLink);
    if (links.length < 5) links.push(rawLink);
  }
  return links;
}

function rows(value, textField, textLimit, extraBuilder) {
  if (!Array.isArray(value)) {
    partial = true;
    return [];
  }
  const result = [];
  for (const raw of value.slice(0, 10)) {
    if (!isRecord(raw) || typeof raw.keyword !== 'string' || !allowedKeywords.has(raw.keyword)) {
      partial = true;
      continue;
    }
    const text = boundedText(raw[textField], textLimit);
    const links = evidenceLinks(raw.evidence_links);
    if (!text || links.length === 0) {
      partial = true;
      continue;
    }
    result.push({ keyword: raw.keyword, [textField]: text, evidence_links: links, ...extraBuilder(raw) });
    if (result.length === 5) break;
  }
  return result;
}

const priorityOpportunities = rows(
  candidate.priority_opportunities,
  'rationale',
  1200,
  (row) => ({ priority: boundedText(row.priority, 80) || 'Evidence review' })
);
const recommendedActions = rows(
  candidate.recommended_actions,
  'action',
  1200,
  () => ({})
);
const hypotheses = rows(
  candidate.hypotheses,
  'hypothesis',
  1200,
  () => ({})
);
const executiveSummary = boundedText(candidate.executive_summary, 2000);
const confidenceExplanation = boundedText(candidate.confidence_explanation, 1500);
if (!executiveSummary || !confidenceExplanation) partial = true;

return [{
  json: {
    ...facts,
    limitations: facts.report_meta.limitations,
    ai_analysis: {
      executive_summary: executiveSummary,
      priority_opportunities: priorityOpportunities,
      recommended_actions: recommendedActions,
      hypotheses,
      confidence_explanation: confidenceExplanation
    },
    ai_analysis_status: partial ? 'partial' : 'completed'
  }
}];

const fields = ["record_type","run_id","run_time","target_domain","region","language","search_depth","api_charge_count","keyword","target_found","target_rank_in_results","target_url","visibility_label","search_status","error_message","serp_evidence_json","competitor_domain","competitor_found","competitor_rank","competitor_url","above_target","opportunity_level","basis","recommended_action","recommendation_type","evidence_link","evidence_links","limitation"];
const report = $input.first().json;
const run = report.run_summary;
const meta = report.report_meta;
if (!run || !meta) throw new Error('Parsed SEO report is required');

const common = {
  run_id: run.run_id,
  run_time: run.run_time,
  target_domain: run.target_domain,
  region: run.region,
  language: run.language,
  search_depth: run.search_depth,
  api_charge_count: run.api_charge_count
};

function unifiedRow(recordType, values) {
  const row = Object.fromEntries(fields.map((field) => [field, '']));
  return { ...row, record_type: recordType, ...common, ...values };
}

const output = [];

for (const row of Array.isArray(report.visibility_summary) ? report.visibility_summary : []) {
  output.push({ json: unifiedRow('visibility', {
    keyword: row.keyword,
    target_found: row.target_found,
    target_rank_in_results: row.target_rank_in_results,
    target_url: row.target_url,
    visibility_label: row.visibility_label,
    search_status: row.search_status,
    error_message: row.error_message,
    evidence_link: row.evidence_link,
    serp_evidence_json: JSON.stringify(row.serp_evidence || []),
    limitation: row.limitation
  }) });
}

for (const row of Array.isArray(report.competitor_presence) ? report.competitor_presence : []) {
  output.push({ json: unifiedRow('competitor', {
    keyword: row.keyword,
    competitor_domain: row.competitor_domain,
    competitor_found: row.competitor_found,
    competitor_rank: row.competitor_rank,
    competitor_url: row.competitor_url,
    above_target: row.above_target,
    evidence_link: row.evidence_link,
    limitation: 'Competitor presence is limited to the current returned SERP evidence.'
  }) });
}

for (const row of Array.isArray(report.keyword_opportunities) ? report.keyword_opportunities : []) {
  output.push({ json: unifiedRow('opportunity', {
    keyword: row.keyword,
    opportunity_level: row.opportunity_level,
    basis: JSON.stringify(row.basis || []),
    recommended_action: row.recommended_action,
    recommendation_type: row.recommendation_type,
    evidence_links: JSON.stringify(row.evidence_links || []),
    limitation: row.limitation
  }) });
}

if (output.length === 0) throw new Error('No Google Sheets rows were produced');
return output;
